// ChallengeRunner.cs
// -----------------------------------------------------------------------------
// VR "Hacker Den" puzzle stage manager.
//
// This single MonoBehaviour drives every challenge station in the level. Level
// designers wire up prefabs and UI references in the Inspector; they never need
// to touch this file. All puzzle logic is abstract and in-memory: no SQL engine,
// no unsafe code, no file/network/process access. Everything here is safe by
// design and meant purely for education.
//
// Junior dev notes:
//  * A "station" is one puzzle in the room. Each station has its own state
//    machine (Brief -> Attempt -> Hint -> Resolved).
//  * The runner owns scoring, hint budgets, and the debrief panel.
//  * Events (OnStationStateChanged, OnScoreChanged, OnDebriefShown) let audio
//    and VFX scripts react without coupling to this file.
// -----------------------------------------------------------------------------

using System;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.Events;
using UnityEngine.UI;

namespace HackerDen
{
    // -------------------------------------------------------------------------
    // Enums
    // -------------------------------------------------------------------------

    /// <summary>Which educational puzzle a station represents.</summary>
    public enum ChallengeKind
    {
        VulnerableLogin,   // SQL-injection-style input concatenation (mocked)
        MemoryCorruption,  // Abstract buffer overflow meter
        Misconfiguration   // Least-privilege permission toggles
    }

    /// <summary>State machine states for a single station.</summary>
    public enum StationState
    {
        Brief,      // Player is reading the intro
        Attempt,    // Player is actively solving
        Hint,       // A hint has been revealed (still solvable)
        Resolved    // Solved; debrief unlocked
    }

    // -------------------------------------------------------------------------
    // Serializable data
    // -------------------------------------------------------------------------

    /// <summary>
    /// One station entry. Designers fill this in via the Inspector.
    /// </summary>
    [Serializable]
    public class StationDefinition
    {
        [Tooltip("Stable ID used by save/telemetry. Must be unique.")]
        public string stationId = "station_01";

        [Tooltip("Which puzzle logic to run for this station.")]
        public ChallengeKind kind = ChallengeKind.VulnerableLogin;

        [Tooltip("Display name shown in the HUD.")]
        public string displayName = "Untitled Station";

        [Tooltip("Points awarded on first solve.")]
        public int basePoints = 100;

        [Tooltip("Points deducted per hint used (floor at 0).")]
        public int hintPenalty = 25;

        [Tooltip("Max hints the player may reveal at this station.")]
        public int maxHints = 3;

        [Header("UI References (optional; wire in Inspector)")]
        public GameObject stationRoot;      // Root of the station's world-space UI
        public Text titleText;              // Station title
        public Text bodyText;               // Brief / attempt / hint text
        public Text statusText;             // "Attempting", "Solved", etc.
        public Button primaryButton;        // "Begin" / "Submit" / "Continue"
        public Button hintButton;           // "Reveal Hint"
        public GameObject resolvedBadge;    // Shown when solved

        [Header("Per-Station Events")]
        public UnityEvent onEnteredBrief;
        public UnityEvent onEnteredAttempt;
        public UnityEvent onEnteredHint;
        public UnityEvent onResolved;
    }

    /// <summary>Runtime state for a station (not serialized).</summary>
    public class StationRuntime
    {
        public StationDefinition def;
        public StationState state = StationState.Brief;
        public int hintsUsed = 0;
        public bool solved = false;
        public int awardedPoints = 0;

        // Puzzle-specific scratch state (kept abstract & in-memory).
        public string loginInput = "";
        public int bufferSize = 8;
        public int overflowMeter = 0;      // 0..100
        public readonly HashSet<string> enabledPermissions = new HashSet<string>();
    }

    // -------------------------------------------------------------------------
    // ChallengeRunner
    // -------------------------------------------------------------------------

    public class ChallengeRunner : MonoBehaviour
    {
        // ---- Inspector fields -------------------------------------------------

        [Header("Stations")]
        [Tooltip("All stations in the level. Order is display order.")]
        public List<StationDefinition> stations = new List<StationDefinition>();

        [Header("Global UI")]
        public Text scoreText;
        public Text hintBudgetText;
        public GameObject debriefPanel;
        public Text debriefTitleText;
        public Text debriefBodyText;
        public Button debriefCloseButton;

        [Header("Global Events")]
        public UnityEvent onScoreChanged;
        public UnityEvent onAllStationsResolved;
        public UnityEvent onDebriefShown;

        // ---- Runtime state ----------------------------------------------------

        private readonly Dictionary<string, StationRuntime> _runtime =
            new Dictionary<string, StationRuntime>();

        private int _totalScore = 0;
        private int _totalHintsUsed = 0;
        private int _resolvedCount = 0;

        // Mock "database" for the login station. Purely in-memory strings.
        private static readonly Dictionary<string, string> MockUsers =
            new Dictionary<string, string>(StringComparer.Ordinal)
            {
                { "alice", "wonderland" },
                { "bob",   "builder"    },
                { "admin", "s3cr3t!"    }
            };

        // ---------------------------------------------------------------------
        // Unity lifecycle
        // ---------------------------------------------------------------------

        private void Awake()
        {
            // Build runtime records and validate IDs.
            var seen = new HashSet<string>();
            foreach (var def in stations)
            {
                if (def == null) continue;
                if (string.IsNullOrEmpty(def.stationId))
                {
                    Debug.LogWarning("[ChallengeRunner] Station with empty ID skipped.");
                    continue;
                }
                if (!seen.Add(def.stationId))
                {
                    Debug.LogError($"[ChallengeRunner] Duplicate station ID '{def.stationId}'.");
                    continue;
                }
                _runtime[def.stationId] = new StationRuntime { def = def };
            }

            if (debriefCloseButton != null)
                debriefCloseButton.onClick.AddListener(HideDebrief);

            if (debriefPanel != null)
                debriefPanel.SetActive(false);
        }

        private void Start()
        {
            // Enter every station's Brief state and refresh HUD.
            foreach (var rt in _runtime.Values)
                EnterState(rt, StationState.Brief);

            RefreshHud();
        }

        // ---------------------------------------------------------------------
        // Public API (called by UI buttons wired in the Inspector)
        // ---------------------------------------------------------------------

        /// <summary>Advance a station from Brief -> Attempt.</summary>
        public void BeginStation(string stationId)
        {
            if (!TryGet(stationId, out var rt)) return;
            if (rt.state != StationState.Brief) return;
            EnterState(rt, StationState.Attempt);
        }

        /// <summary>Reveal a hint (if budget allows).</summary>
        public void RevealHint(string stationId)
        {
            if (!TryGet(stationId, out var rt)) return;
            if (rt.solved) return;
            if (rt.hintsUsed >= rt.def.maxHints)
            {
                SetBody(rt, "No hints remaining at this station.");
                return;
            }
            rt.hintsUsed++;
            _totalHintsUsed++;
            EnterState(rt, StationState.Hint);
            RefreshHud();
        }

        /// <summary>
        /// Submit an answer for the login station. Returns true if solved.
        /// </summary>
        public bool SubmitLogin(string stationId, string userInput)
        {
            if (!TryGet(stationId, out var rt)) return false;
            if (rt.def.kind != ChallengeKind.VulnerableLogin) return false;
            if (rt.solved) return true;

            rt.loginInput = userInput ?? "";

            // The "vulnerable" behavior: input is concatenated into a query
            // string. We simulate the classic bypass with a harmless mock.
            // A correct solution demonstrates awareness of the injection.
            bool bypass = LooksLikeInjection(rt.loginInput);
            bool legit  = TryMockLogin(rt.loginInput);

            if (bypass || legit)
            {
                Resolve(rt);
                return true;
            }

            SetBody(rt, "Login failed. The form concatenates your input directly " +
                        "into the query. Can you make the query always true?");
            return false;
        }

        /// <summary>Set the buffer size for the memory-corruption station.</summary>
        public void SetBufferSize(string stationId, int size)
        {
            if (!TryGet(stationId, out var rt)) return;
            if (rt.def.kind != ChallengeKind.MemoryCorruption) return;
            if (rt.solved) return;

            rt.bufferSize = Mathf.Clamp(size, 1, 64);

            // Abstract overflow meter: the "input" is a fixed 32-byte payload.
            // If the buffer is smaller, the meter rises. No real memory is
            // touched; this is a teaching metaphor.
            const int payload = 32;
            int overflow = Mathf.Max(0, payload - rt.bufferSize);
